discrete SignalAcquisitionSystem
port:
    event input real DetectSignal;
    event output real SendData;
state:
    initial state Initialization
        when entry() then
            statehold(0);
        end;
        when receive(DetectSignal) then
            transition(SignalReading);
        end;
    end;

    state SignalReading
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(Initialization);
            out
                send(SendData, 1);
            end;
        end;
    end;
end;
end;

discrete SignalProcessingSystem
port:
    event input real ReceiveData;
    event output real SendProcessedData;
state:
    initial state Idle
        when entry() then
            statehold(0);
        end;
        when receive(ReceiveData) then
            transition(DataAnalysis);
        end;
    end;

    state DataAnalysis
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(Idle);
            out
                send(SendProcessedData, 1);
            end;
        end;
    end;
end;
end;

discrete DataOutputSystem
port:
    event input real ReceiveProcessedData;
    event output real DataTransmissionComplete;
state:
    initial state Standby
        when entry() then
            statehold(0);
        end;
        when receive(ReceiveProcessedData) then
            transition(DataTransmission);
        end;
    end;

    state DataTransmission
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(Standby);
            out
                send(DataTransmissionComplete, 1);
            end;
        end;
    end;
end;
end;

